<?php
declare(strict_types=1); require_once __DIR__.'/../includes/layout.php'; require_admin();$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');$where='';$args=[];if($from&&$to){$where=' WHERE DATE(r.borrowed_at) BETWEEN ? AND ?';$args=[$from,$to];}$s=db()->prepare("SELECT r.*,b.title,COALESCE(u.fullname,r.walkin_name) customer FROM rentals r JOIN books b ON b.id=r.book_id LEFT JOIN users u ON u.id=r.user_id $where ORDER BY r.borrowed_at DESC");$s->execute($args);$rows=$s->fetchAll();$rental=array_sum(array_column($rows,'rental_total'));$fine=array_sum(array_column($rows,'fine'));page_start('รายได้','revenue'); ?>
<div class="page-head"><div><h1>รายได้</h1><p>สรุปค่าเช่าและค่าปรับจากรายการจริง</p></div></div><form class="filters"><label class="field">ตั้งแต่<input type="date" name="from" value="<?=e($from)?>"></label><label class="field">ถึง<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn">กรองช่วงเวลา</button></form><section class="cards" style="grid-template-columns:repeat(3,1fr)"><article class="stat"><small>รายได้ค่าเช่า</small><b><?=number_format($rental,2)?> ฿</b></article><article class="stat"><small>รายได้ค่าปรับ</small><b><?=number_format($fine,2)?> ฿</b></article><article class="stat"><small>รายได้รวม</small><b><?=number_format($rental+$fine,2)?> ฿</b></article></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>ลูกค้า</th><th>หนังสือ</th><th>เริ่มเช่า</th><th>คืนจริง</th><th>ค่าเช่า</th><th>ค่าปรับ</th><th>รวม</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['customer'])?></td><td><?=e($r['title'])?></td><td><?=thai_date($r['borrowed_at'],true)?></td><td><?=thai_date($r['returned_at'],true)?></td><td><?=number_format($r['rental_total'],2)?></td><td><?=number_format($r['fine'],2)?></td><td class="money"><?=number_format($r['rental_total']+$r['fine'],2)?> บาท</td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="7" class="empty">ยังไม่มีข้อมูลรายได้</td></tr><?php endif?></tbody></table></div></section>
<?php page_end(); ?>
